from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # The frequent non-background color marks locations to receive the template.
    nonbg = [(v, n) for v, n in counts.items() if v != background]
    target = max(nonbg, key=lambda p: p[1])[0]
    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if not anchors:
        return [row[:] for row in grid]
    ar, ac = anchors[0]
    template = [(r-ar, c-ac, grid[r][c])
                for r in range(h) for c in range(w)
                if grid[r][c] != background and grid[r][c] != target]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target:
                for dr, dc, color in template:
                    rr, cc = r+dr, c+dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out

